/**
 * CartGuard Validator — Function OUTPUT contract (committed by hand).
 *
 * The purchase.validation.run result schema is stable and small, so unlike
 * the input types (generated by graphql-codegen into gitignored
 * generated/api.ts) the output contract lives in source control.
 *
 * Return format: the direct `{ errors }` shape was attempted first per the
 * architecture protocol and FAILED to type-check; the wrapped
 * `operations → validationAdd → errors` shape below is the one that compiles
 * against the 2026-07 purchase.validation contract.
 */

export type FunctionError = {
  /** Buyer-facing message shown in checkout. */
  localizedMessage: string;
  /** JSONPath into the Function input that the error refers to. */
  target: string;
};

export type FunctionResult = {
  operations: Array<{
    validationAdd: {
      errors: FunctionError[];
    };
  }>;
};
